package com.amit.jobagent.application;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="application_timeline_event")class ApplicationTimelineEvent{@Id UUID id;@Column(name="application_tracker_id",nullable=false,updatable=false)UUID trackerId;@Column(name="event_type",nullable=false,updatable=false,length=40)String type;@Enumerated(EnumType.STRING)@Column(name="previous_status",updatable=false,length=30)ApplicationTrackingStatus previous;@Enumerated(EnumType.STRING)@Column(name="new_status",updatable=false,length=30)ApplicationTrackingStatus next;@Column(nullable=false,updatable=false,length=30)String source;@Column(length=1000,updatable=false)String note;@Column(name="created_by",nullable=false,updatable=false,length=150)String actor;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;protected ApplicationTimelineEvent(){}ApplicationTimelineEvent(UUID tracker,String type,ApplicationTrackingStatus old,ApplicationTrackingStatus next,String source,String note,String actor){id=UUID.randomUUID();trackerId=tracker;this.type=type;previous=old;this.next=next;this.source=source;this.note=note;this.actor=actor;createdAt=Instant.now();}}
